import re


# Функция для добавления нижнего индекса и выделения курсивом переменных
def ssstyle(text):
    text = re.sub(r'\(([^)]+)\)', r'<sub>\1</sub>', text)
    text = re.sub(r'(\d+)', r'<sub>\1</sub>', text)
    return "<em>" + text + "</em>"


